with "heaps.gpr";
project Fuzz is
   for Source_Dirs use (".");
   for Object_Dir use "obj";
   for Exec_Dir use ".";
   for Main use ("fuzz_main.adb");
   package Compiler is
      for Default_Switches ("Ada") use ("-gnat2022", "-O0", "-gnata", "-gnatwa");
   end Compiler;
end Fuzz;
