SP=<scratch>; cat > $SP/fuzz_main.adb <<'EOF'
with Ada.Text_IO; use Ada.Text_IO;
with Heaps; use Heaps;
with Heaps.Tournament;
with Heaps.Min_Max_Tournament;
with Heaps.Sorted_Linked;
with Heaps.Bucket;

procedure Fuzz_Main is

   Failures : Natural := 0;

   State : Long_Long_Integer := 12345;
   function Rnd (M : Positive) return Natural is
   begin
      State := (State * 1_103_515_245 + 12_345) mod 2_147_483_647;
      return Natural (State mod Long_Long_Integer (M));
   end Rnd;

   --  Reference: a plain sorted (ascending) list of keys.
   type Ref_Array is array (1 .. 4096) of Key_Type;
   Ref     : Ref_Array;
   Ref_Len : Natural := 0;

   procedure Ref_Clear is
   begin
      Ref_Len := 0;
   end Ref_Clear;

   procedure Ref_Insert (K : Key_Type) is
      P : Natural := Ref_Len;
   begin
      while P >= 1 and then Ref (P) > K loop
         Ref (P + 1) := Ref (P);
         P := P - 1;
      end loop;
      Ref (P + 1) := K;
      Ref_Len := Ref_Len + 1;
   end Ref_Insert;

   function Ref_Min return Key_Type is (Ref (1));
   function Ref_Max return Key_Type is (Ref (Ref_Len));

   procedure Ref_Del_Min is
   begin
      for I in 1 .. Ref_Len - 1 loop
         Ref (I) := Ref (I + 1);
      end loop;
      Ref_Len := Ref_Len - 1;
   end Ref_Del_Min;

   procedure Ref_Del_Max is
   begin
      Ref_Len := Ref_Len - 1;
   end Ref_Del_Max;

   procedure Fail (Msg : String) is
   begin
      Put_Line ("FAIL: " & Msg);
      Failures := Failures + 1;
   end Fail;

   ----------------
   -- Tournament --
   ----------------

   procedure Run_Tournament (Cap : Positive; Steps : Positive; Span : Positive) is
      H : Heaps.Tournament.Heap (Extended_Index (Cap));
      K : Key_Type;
   begin
      Heaps.Tournament.Clear (H);
      Ref_Clear;
      for S in 1 .. Steps loop
         if Ref_Len = 0 or else (Ref_Len < Cap and then Rnd (2) = 0) then
            K := Key_Type (Rnd (Span));
            Heaps.Tournament.Insert (H, K);
            Ref_Insert (K);
         else
            if Heaps.Tournament.Peek_Min (H) /= Ref_Min then
               Fail ("tournament peek cap=" & Cap'Image & " step" & S'Image);
               return;
            end if;
            Heaps.Tournament.Extract_Min (H, K);
            if K /= Ref_Min then
               Fail ("tournament extract cap=" & Cap'Image & " step" & S'Image);
               return;
            end if;
            Ref_Del_Min;
         end if;
         if Natural (Heaps.Tournament.Size (H)) /= Ref_Len then
            Fail ("tournament size cap=" & Cap'Image);
            return;
         end if;
      end loop;
   end Run_Tournament;

   procedure Run_Tournament_Meld (A, B : Natural) is
      Cap  : constant Extended_Index := Extended_Index (A + B + 1);
      X, Y : Heaps.Tournament.Heap (Cap);
      K    : Key_Type;
   begin
      Heaps.Tournament.Clear (X);
      Heaps.Tournament.Clear (Y);
      Ref_Clear;
      for I in 1 .. A loop
         K := Key_Type (Rnd (50));
         Heaps.Tournament.Insert (X, K);
         Ref_Insert (K);
      end loop;
      for I in 1 .. B loop
         K := Key_Type (Rnd (50));
         Heaps.Tournament.Insert (Y, K);
         Ref_Insert (K);
      end loop;
      Heaps.Tournament.Meld (X, Y);
      if not Heaps.Tournament.Is_Empty (Y) then
         Fail ("tournament meld source not empty");
      end if;
      while Ref_Len > 0 loop
         Heaps.Tournament.Extract_Min (X, K);
         if K /= Ref_Min then
            Fail ("tournament meld order");
            return;
         end if;
         Ref_Del_Min;
      end loop;
      if not Heaps.Tournament.Is_Empty (X) then
         Fail ("tournament meld leftovers");
      end if;
   end Run_Tournament_Meld;

   ------------------------
   -- Min_Max_Tournament --
   ------------------------

   procedure Run_MMT (Cap : Positive; Steps : Positive; Span : Positive) is
      H : Heaps.Min_Max_Tournament.Heap (Extended_Index (Cap));
      K : Key_Type;
   begin
      Heaps.Min_Max_Tournament.Clear (H);
      Ref_Clear;
      for S in 1 .. Steps loop
         if Ref_Len = 0 or else (Ref_Len < Cap and then Rnd (2) = 0) then
            K := Key_Type (Rnd (Span));
            Heaps.Min_Max_Tournament.Insert (H, K);
            Ref_Insert (K);
         elsif Rnd (2) = 0 then
            if Heaps.Min_Max_Tournament.Peek_Min (H) /= Ref_Min then
               Fail ("mmt peek min cap=" & Cap'Image & " step" & S'Image);
               return;
            end if;
            Heaps.Min_Max_Tournament.Extract_Min (H, K);
            if K /= Ref_Min then
               Fail ("mmt extract min cap=" & Cap'Image & " step" & S'Image);
               return;
            end if;
            Ref_Del_Min;
         else
            if Heaps.Min_Max_Tournament.Peek_Max (H) /= Ref_Max then
               Fail ("mmt peek max cap=" & Cap'Image & " step" & S'Image);
               return;
            end if;
            Heaps.Min_Max_Tournament.Extract_Max (H, K);
            if K /= Ref_Max then
               Fail ("mmt extract max cap=" & Cap'Image & " step" & S'Image);
               return;
            end if;
            Ref_Del_Max;
         end if;
         if Natural (Heaps.Min_Max_Tournament.Size (H)) /= Ref_Len then
            Fail ("mmt size cap=" & Cap'Image);
            return;
         end if;
      end loop;
   end Run_MMT;

   -------------------
   -- Sorted_Linked --
   -------------------

   procedure Run_Sorted_Linked (Cap : Positive; Steps : Positive; Span : Positive) is
      H : Heaps.Sorted_Linked.Heap (Extended_Index (Cap));
      K : Key_Type;
   begin
      Heaps.Sorted_Linked.Clear (H);
      Ref_Clear;
      for S in 1 .. Steps loop
         if Ref_Len = 0 or else (Ref_Len < Cap and then Rnd (2) = 0) then
            K := Key_Type (Rnd (Span));
            Heaps.Sorted_Linked.Insert (H, K);
            Ref_Insert (K);
         else
            if Heaps.Sorted_Linked.Peek_Min (H) /= Ref_Min then
               Fail ("linked peek cap=" & Cap'Image & " step" & S'Image);
               return;
            end if;
            Heaps.Sorted_Linked.Extract_Min (H, K);
            if K /= Ref_Min then
               Fail ("linked extract cap=" & Cap'Image & " step" & S'Image);
               return;
            end if;
            Ref_Del_Min;
         end if;
         if Natural (Heaps.Sorted_Linked.Size (H)) /= Ref_Len then
            Fail ("linked size cap=" & Cap'Image);
            return;
         end if;
      end loop;
   end Run_Sorted_Linked;

   procedure Run_Linked_Meld (A, B : Natural) is
      Cap  : constant Extended_Index := Extended_Index (A + B + 1);
      X, Y : Heaps.Sorted_Linked.Heap (Cap);
      K    : Key_Type;
   begin
      Heaps.Sorted_Linked.Clear (X);
      Heaps.Sorted_Linked.Clear (Y);
      Ref_Clear;
      for I in 1 .. A loop
         K := Key_Type (Rnd (30));
         Heaps.Sorted_Linked.Insert (X, K);
         Ref_Insert (K);
      end loop;
      for I in 1 .. B loop
         K := Key_Type (Rnd (30));
         Heaps.Sorted_Linked.Insert (Y, K);
         Ref_Insert (K);
      end loop;
      Heaps.Sorted_Linked.Meld (X, Y);
      while Ref_Len > 0 loop
         Heaps.Sorted_Linked.Extract_Min (X, K);
         if K /= Ref_Min then
            Fail ("linked meld order");
            return;
         end if;
         Ref_Del_Min;
      end loop;
   end Run_Linked_Meld;

   ------------
   -- Bucket --
   ------------

   procedure Run_Bucket (Cap : Positive; Steps : Positive; Lo, Hi : Key_Type) is
      H : Heaps.Bucket.Heap (Extended_Index (Cap), Lo, Hi);
      K : Key_Type;
   begin
      Heaps.Bucket.Clear (H);
      Ref_Clear;
      for S in 1 .. Steps loop
         if Ref_Len = 0 or else (Ref_Len < Cap and then Rnd (2) = 0) then
            K := Lo + Key_Type (Rnd (Natural (Hi - Lo) + 1));
            Heaps.Bucket.Insert (H, K);
            Ref_Insert (K);
         else
            if Heaps.Bucket.Peek_Min (H) /= Ref_Min then
               Fail ("bucket peek cap=" & Cap'Image & " step" & S'Image);
               return;
            end if;
            Heaps.Bucket.Extract_Min (H, K);
            if K /= Ref_Min then
               Fail ("bucket extract cap=" & Cap'Image & " step" & S'Image);
               return;
            end if;
            Ref_Del_Min;
         end if;
         if Natural (Heaps.Bucket.Size (H)) /= Ref_Len then
            Fail ("bucket size cap=" & Cap'Image);
            return;
         end if;
      end loop;
   end Run_Bucket;

   procedure Run_Bucket_Meld (A, B : Natural) is
      Cap  : constant Extended_Index := Extended_Index (A + B + 1);
      X    : Heaps.Bucket.Heap (Cap, -10, 10);
      Y    : Heaps.Bucket.Heap (Cap, -3, 7);
      K    : Key_Type;
   begin
      Heaps.Bucket.Clear (X);
      Heaps.Bucket.Clear (Y);
      Ref_Clear;
      for I in 1 .. A loop
         K := -10 + Key_Type (Rnd (21));
         Heaps.Bucket.Insert (X, K);
         Ref_Insert (K);
      end loop;
      for I in 1 .. B loop
         K := -3 + Key_Type (Rnd (11));
         Heaps.Bucket.Insert (Y, K);
         Ref_Insert (K);
      end loop;
      Heaps.Bucket.Meld (X, Y);
      if not Heaps.Bucket.Is_Empty (Y) then
         Fail ("bucket meld source not empty");
      end if;
      while Ref_Len > 0 loop
         Heaps.Bucket.Extract_Min (X, K);
         if K /= Ref_Min then
            Fail ("bucket meld order");
            return;
         end if;
         Ref_Del_Min;
      end loop;
   end Run_Bucket_Meld;

begin
   for Cap in 1 .. 20 loop
      Run_Tournament (Cap, 400, 7);
      Run_Tournament (Cap, 400, 1000);
      Run_MMT (Cap, 400, 7);
      Run_MMT (Cap, 400, 1000);
      Run_Sorted_Linked (Cap, 400, 7);
      Run_Sorted_Linked (Cap, 400, 1000);
      Run_Bucket (Cap, 400, -3, 3);
      Run_Bucket (Cap, 400, 0, 0);
      Run_Bucket (Cap, 400, -50, 50);
   end loop;

   Run_Tournament (300, 20_000, 500);
   Run_MMT (300, 20_000, 500);
   Run_Sorted_Linked (300, 5_000, 500);
   Run_Bucket (300, 20_000, -60, 60);

   for A in 0 .. 8 loop
      for B in 0 .. 8 loop
         Run_Tournament_Meld (A, B);
         Run_Linked_Meld (A, B);
         Run_Bucket_Meld (A, B);
      end loop;
   end loop;
   Run_Tournament_Meld (100, 60);
   Run_Linked_Meld (100, 60);
   Run_Bucket_Meld (100, 60);

   if Failures = 0 then
      Put_Line ("differential fuzz: all checks passed");
   else
      Put_Line ("differential fuzz:" & Failures'Image & " failures");
   end if;
end Fuzz_Main;
EOF
cd $SP && gprbuild -P fuzz.gpr -j8 2>&1 | tail -20

SP=<scratch>; cat > $SP/fuzz_radix.adb <<'EOF'
with Ada.Text_IO; use Ada.Text_IO;
with Heaps; use Heaps;
with Heaps.Radix;

procedure Fuzz_Radix is
   Failures : Natural := 0;
   State : Long_Long_Integer := 999_331;
   function Rnd (M : Positive) return Natural is
   begin
      State := (State * 1_103_515_245 + 12_345) mod 2_147_483_647;
      return Natural (State mod Long_Long_Integer (M));
   end Rnd;

   type Ref_Array is array (1 .. 8192) of Key_Type;
   Ref : Ref_Array; Ref_Len : Natural := 0;

   procedure Ref_Insert (K : Key_Type) is
      P : Natural := Ref_Len;
   begin
      while P >= 1 and then Ref (P) > K loop
         Ref (P + 1) := Ref (P); P := P - 1;
      end loop;
      Ref (P + 1) := K; Ref_Len := Ref_Len + 1;
   end Ref_Insert;

   function Ref_Min return Key_Type is (Ref (1));
   procedure Ref_Del_Min is
   begin
      for I in 1 .. Ref_Len - 1 loop Ref (I) := Ref (I + 1); end loop;
      Ref_Len := Ref_Len - 1;
   end Ref_Del_Min;

   procedure Fail (Msg : String) is
   begin
      Put_Line ("FAIL: " & Msg); Failures := Failures + 1;
   end Fail;

   --  Monotone mixed workload: never insert below the last extracted key.
   procedure Run (Cap : Positive; Steps : Positive; Span : Positive;
                  Start : Key_Type) is
      H    : Heaps.Radix.Heap (Extended_Index (Cap));
      K    : Key_Type;
      Base : Key_Type := Start;
   begin
      Heaps.Radix.Clear (H);
      Ref_Len := 0;
      for S in 1 .. Steps loop
         if Ref_Len = 0 or else (Ref_Len < Cap and then Rnd (2) = 0) then
            K := Base + Key_Type (Rnd (Span));
            Heaps.Radix.Insert (H, K);
            Ref_Insert (K);
         else
            if Heaps.Radix.Peek_Min (H) /= Ref_Min then
               Fail ("radix peek cap=" & Cap'Image & " step" & S'Image);
               return;
            end if;
            Heaps.Radix.Extract_Min (H, K);
            if K /= Ref_Min then
               Fail ("radix extract cap=" & Cap'Image & " step" & S'Image);
               return;
            end if;
            if H.Base /= K then
               Fail ("radix base not advanced");
               return;
            end if;
            Base := K;
            Ref_Del_Min;
         end if;
         if Natural (Heaps.Radix.Size (H)) /= Ref_Len then
            Fail ("radix size cap=" & Cap'Image);
            return;
         end if;
      end loop;
   end Run;

   --  Keys placed exactly on the bucket boundaries around a moving base.
   procedure Run_Boundaries is
      H : Heaps.Radix.Heap (200);
      K : Key_Type;
      P : Key_Type;
   begin
      Heaps.Radix.Clear (H);
      Ref_Len := 0;
      P := 1;
      for B in 1 .. 29 loop
         for D in Key_Type'(-1) .. 1 loop
            if P + D >= 0 then
               Heaps.Radix.Insert (H, P + D);
               Ref_Insert (P + D);
            end if;
         end loop;
         P := 2 * P;
      end loop;
      while Ref_Len > 0 loop
         Heaps.Radix.Extract_Min (H, K);
         if K /= Ref_Min then
            Fail ("radix boundary order, got" & K'Image
                  & " want" & Ref_Min'Image);
            return;
         end if;
         Ref_Del_Min;
      end loop;
   end Run_Boundaries;

   --  Very large keys, near the top bucket.
   procedure Run_Large is
      H : Heaps.Radix.Heap (100);
      K : Key_Type;
   begin
      Heaps.Radix.Clear (H);
      Ref_Len := 0;
      for I in 1 .. 100 loop
         K := Key_Type (Rnd (1_000)) + Key_Type'(2_147_000_000)
              - Key_Type (Rnd (2_000_000_000));
         if K < 0 then K := 0; end if;
         Heaps.Radix.Insert (H, K);
         Ref_Insert (K);
      end loop;
      while Ref_Len > 0 loop
         Heaps.Radix.Extract_Min (H, K);
         if K /= Ref_Min then
            Fail ("radix large-key order"); return;
         end if;
         Ref_Del_Min;
      end loop;
   end Run_Large;

   --  Meld where the destination base is already ahead of the source base.
   procedure Run_Meld (A, B : Natural) is
      Cap  : constant Extended_Index := Extended_Index (A + B + 2);
      X, Y : Heaps.Radix.Heap (Cap);
      K    : Key_Type;
   begin
      Heaps.Radix.Clear (X);
      Heaps.Radix.Clear (Y);
      Ref_Len := 0;
      --  Advance X's base first.
      Heaps.Radix.Insert (X, 1_000);
      Heaps.Radix.Extract_Min (X, K);
      for I in 1 .. A loop
         K := 1_000 + Key_Type (Rnd (5_000));
         Heaps.Radix.Insert (X, K); Ref_Insert (K);
      end loop;
      for I in 1 .. B loop
         K := 1_000 + Key_Type (Rnd (5_000));
         Heaps.Radix.Insert (Y, K); Ref_Insert (K);
      end loop;
      Heaps.Radix.Meld (X, Y);
      if not Heaps.Radix.Is_Empty (Y) then
         Fail ("radix meld source not empty");
      end if;
      while Ref_Len > 0 loop
         Heaps.Radix.Extract_Min (X, K);
         if K /= Ref_Min then Fail ("radix meld order"); return; end if;
         Ref_Del_Min;
      end loop;
   end Run_Meld;

begin
   for Cap in 1 .. 20 loop
      Run (Cap, 400, 5, 0);
      Run (Cap, 400, 100_000, 0);
      Run (Cap, 400, 3, 2_000_000_000);
   end loop;
   Run (500, 20_000, 1_000, 0);
   Run_Boundaries;
   Run_Large;
   for A in 0 .. 8 loop
      for B in 0 .. 8 loop
         Run_Meld (A, B);
      end loop;
   end loop;
   Run_Meld (100, 60);

   if Failures = 0 then
      Put_Line ("radix differential fuzz: all checks passed");
   else
      Put_Line ("radix differential fuzz:" & Failures'Image & " failures");
   end if;
end Fuzz_Radix;
EOF
sed -i 's/for Main use ("fuzz_main.adb");/for Main use ("fuzz_main.adb", "fuzz_radix.adb");/' $SP/fuzz.gpr
cd $SP && gprbuild -P fuzz.gpr -j8 2>&1 | tail -10 && ./fuzz_radix

