SP=<scratch>; mkdir -p $SP/altfuzz/obj; cp $SP/fuzz_radix.adb $SP/altfuzz/; cat > $SP/altfuzz/altfuzz.gpr <<EOF
with "$SP/alt/alt.gpr";
project Altfuzz is
   for Source_Dirs use (".");
   for Object_Dir use "obj";
   for Exec_Dir use ".";
   for Main use ("fuzz_radix.adb");
   package Compiler is
      for Default_Switches ("Ada") use ("-gnat2022", "-O0", "-gnatwa");
   end Compiler;
end Altfuzz;
EOF
cd $SP/altfuzz && gprbuild -P altfuzz.gpr -j8 2>&1 | tail -6 && ./fuzz_radix

SP=<scratch>
cat > $SP/time_radix.adb <<'EOF'
with Ada.Text_IO; use Ada.Text_IO;
with Ada.Real_Time; use Ada.Real_Time;
with Heaps; use Heaps;
with Heaps.Radix;

procedure Time_Radix is
   N : constant := 10_000;
   H : Heaps.Radix.Heap (N);
   K : Key_Type;
   State : Long_Long_Integer := 42;
   T0, T1, T2 : Time;
   Sum : Long_Long_Integer := 0;
begin
   Heaps.Radix.Clear (H);
   T0 := Clock;
   for I in 1 .. N loop
      State := (State * 1_103_515_245 + 12_345) mod 2_147_483_647;
      Heaps.Radix.Insert (H, Key_Type (State mod 100_000));
   end loop;
   T1 := Clock;
   for I in 1 .. N loop
      Heaps.Radix.Extract_Min (H, K);
      Sum := Sum + Long_Long_Integer (K);
   end loop;
   T2 := Clock;
   Put_Line ("fill  ns/op:"
     & Duration'Image (To_Duration (T1 - T0) * 1.0e9 / N));
   Put_Line ("drain ns/op:"
     & Duration'Image (To_Duration (T2 - T1) * 1.0e9 / N));
   Put_Line ("checksum:" & Sum'Image);
end Time_Radix;
EOF
cp $SP/time_radix.adb $SP/altfuzz/
sed -i 's/for Main use ("fuzz_main.adb", "fuzz_radix.adb");/for Main use ("fuzz_main.adb", "fuzz_radix.adb", "time_radix.adb");/' $SP/fuzz.gpr
sed -i 's/for Main use ("fuzz_radix.adb");/for Main use ("fuzz_radix.adb", "time_radix.adb");/' $SP/altfuzz/altfuzz.gpr
sed -i 's/"-gnat2022", "-O0", "-gnata", "-gnatwa"/"-gnat2022", "-O2", "-gnatwa"/' $SP/fuzz.gpr
sed -i 's/"-gnat2022", "-O0", "-gnatwa"/"-gnat2022", "-O2", "-gnatwa"/' $SP/altfuzz/altfuzz.gpr
cd $SP && gprbuild -P fuzz.gpr -j8 2>&1 | tail -2 && cd $SP/altfuzz && gprbuild -P altfuzz.gpr -j8 2>&1 | tail -2
echo "=== as committed (with bucket tags) ==="; $SP/time_radix; $SP/time_radix
echo "=== bucket tags deleted ==="; $SP/altfuzz/time_radix; $SP/altfuzz/time_radix

