with Heaps.Radix;

procedure Scale_Radix is
   Max : constant := 1_000_000;
   H : Heaps.Radix.Heap (Max);
   procedure Run (N : Positive) is
      K : Key_Type;
      State : Long_Long_Integer := 42;
      T0, T1, T2 : Time;
      Sum : Long_Long_Integer := 0;
   begin
      Heaps.Radix.Clear (H);
      T0 := Clock;
      for I in 1 .. N loop
         State := (State * 1_103_515_245 + 12_345) mod 2_147_483_647;
         Heaps.Radix.Insert (H, Key_Type (State mod 1_000_000));
      end loop;
      T1 := Clock;
      for I in 1 .. N loop
         Heaps.Radix.Extract_Min (H, K);
         Sum := Sum + Long_Long_Integer (K);
      end loop;
      T2 := Clock;
      Put_Line ("n =" & N'Image
        & "   fill ns/op:" & Duration'Image (To_Duration (T1 - T0) * 1.0e9 / N)
        & "   drain ns/op:" & Duration'Image (To_Duration (T2 - T1) * 1.0e9 / N));
   end Run;
begin
   Run (10_000);
   Run (100_000);
   Run (1_000_000);
end Scale_Radix;
