"""      pragma Assert (H.Keys (Top) = K);
      pragma Assert
        (for all D in J + 1 .. Bucket_Index'Last =>
           (for all I in H.Starts (D) .. H.Starts (D + 1) - 1 =>
              H.Keys (I) <= H.Bound (D)
              and then H.Keys (I) > H.Bound (D - 1)));

      for C in J + 1 .. Bucket_Index'Last loop""")

