           (for all Q in 1 .. D =>
              H.Bound (Q) >= K and then H.Bound (Q) <= H.Bound (J));
         pragma Loop_Invariant
           (for all Q in 1 .. D => H.Bound (Q - 1) <= H.Bound (Q));""",
